type Builder = fn() -> Box<dyn Shape>;
static REGISTRY: OnceLock<HashMap<&'static str, Builder>> = OnceLock::new();

pub fn register(name: &'static str, make: Builder) {
    REGISTRY.get_or_init(HashMap::new).entry(name).or_insert(make);
}

pub fn create(name: &str) -> Option<Box<dyn Shape>> {
    REGISTRY.get().and_then(|m| m.get(name)).map(|make| make())
}
